#!/usr/bin/env python3
"""Independent performance evidence, never a production dependency. Same source
and hardware; compare current default native run/AOT with isolated historical VM
run, label the differing pipelines, report raw samples without inferred speedup.
"""
import argparse,hashlib,json,subprocess,tempfile,shutil,time,re
from pathlib import Path
p=argparse.ArgumentParser(description=__doc__);p.add_argument('--candidate',type=Path,required=True);p.add_argument('--reference',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();root=Path(__file__).resolve().parents[1];out=a.output.resolve();out.mkdir(parents=True,exist_ok=False);work=Path(tempfile.mkdtemp(prefix='mio-perf-final-',dir='/tmp')).resolve();native=work/'native-mio';legacy=work/'legacy-reference';shutil.copy2(a.candidate,native);shutil.copy2(a.reference,legacy);source=work/'case.mio';source.write_text('kaku total=0;kaku at=0;aida(at<100000){total=total+at;at=at+1;}chant(total);\n');results=[]
for repeat in range(6):
 for mode,program in [('native-aot-default',native),('legacy-vm-reference',legacy)]:
  label=mode+'-'+str(repeat);policy=work/(label+'.sb');text='(version 1)(allow default)(deny network*)(deny process-exec)(allow process-exec (literal '+json.dumps(str(program))+'))(deny file-read* (subpath '+json.dumps(str(root))+'))(deny file-read* (subpath "/Volumes/Sector0/AppData/Mio"))'
  if mode=='native-aot-default':text+='(allow process-exec (regex #"^(/private)?/tmp/mio-run-[0-9]+/program$"))'
  else:text+='(deny process-fork)'
  policy.write_text(text+'\n');argv=['/usr/bin/time','-l','/usr/bin/sandbox-exec','-f',str(policy),str(program),'run',str(source)];start=time.monotonic();r=subprocess.run(argv,cwd=work,env={'PATH':'','MIO_BUNKO':''},capture_output=True,timeout=120);seconds=time.monotonic()-start;(out/(label+'.stdout')).write_bytes(r.stdout);(out/(label+'.stderr')).write_bytes(r.stderr);stats=r.stderr.decode(errors='replace');rss=re.search(r'(\d+)\s+maximum resident set size',stats);timing=re.search(r'([\d.]+) real\s+([\d.]+) user\s+([\d.]+) sys',stats);results.append({'mode':mode,'repeat':repeat,'cache_label':'first fresh process; OS cache not flushed' if repeat==0 else 'fresh process with warmed OS caches','exit':r.returncode,'correct_output':r.stdout==b'4999950000\n','wall_seconds':seconds,'rss_bytes':int(rss.group(1)) if rss else None,'time_fields':[float(x) for x in timing.groups()] if timing else None,'argv':argv});(out/'results.json').write_text(json.dumps(results,indent=2)+'\n');print(mode,repeat,r.returncode,round(seconds,4),flush=True)
(out/'provenance.json').write_text(json.dumps({'scope':__doc__,'candidate_sha256':hashlib.sha256(native.read_bytes()).hexdigest(),'reference_sha256':hashlib.sha256(legacy.read_bytes()).hexdigest(),'input_sha256':hashlib.sha256(source.read_bytes()).hexdigest(),'input':source.read_text(),'work':str(work),'limits':'Modes intentionally differ: native includes AOT/sign/spawn; reference executes Go VM. No cold disk-cache claim. Full compiler source timings are separate GF4 evidence; historic compiler source versions differ, so no full-source speed ratio is asserted.'},indent=2)+'\n');raise SystemExit(0 if all(x['exit']==0 and x['correct_output'] for x in results) else 1)
